.save-row { display: grid; grid-template-columns: 1fr auto; gap: 10px; }
.save-row input { min-width: 0; padding: 17px 18px; border: 1px solid #c9c6bc; border-radius: 8px; background: white; color: var(--ink); outline: none; box-shadow: 0 3px 10px rgba(34,35,31,.04); }
.save-row input:focus { border-color: var(--accent); box-shadow: 0 0 0 3px rgba(214,84,54,.13); }
