export function tokenizeQuery(query) {
  const tokens = [];
  let index = 0;
  let unclosedQuote = false;
  while (index < query.length) {
    while (/\s/.test(query[index] || '')) index += 1;
    if (index >= query.length) break;
    let excluded = false;
    if (query[index] === '-') {
      excluded = true;
      index += 1;
    }
    if (query[index] === '"') {
      index += 1;
      const end = query.indexOf('"', index);
      if (end === -1) {
        tokens.push({ value: query.slice(index).trim(), exact: true, excluded, unclosed: true });
        unclosedQuote = true;
        break;
      }
      tokens.push({ value: query.slice(index, end), exact: true, excluded });
      index = end + 1;
      continue;
    }
    let end = index;
    while (end < query.length && !/\s/.test(query[end])) end += 1;
    const value = query.slice(index, end);
    tokens.push({ value, exact: false, excluded, operator: value.toUpperCase() === 'OR' });
    index = end;
  }
  return { tokens: tokens.filter((token) => token.value), unclosedQuote };
}

export function searchableText(bookmark) {
  return [bookmark.title, bookmark.description, bookmark.site, bookmark.url, ...(bookmark.labels || [])].join(' ').toLowerCase();
}

function tokenMatches(bookmark, token) {
  const lowered = token.value.toLowerCase();
  let matches;
  if (lowered.startsWith('label:')) {
    const wanted = lowered.slice(6);
    matches = bookmark.labels.some((label) => label.toLowerCase() === wanted);
  } else {
    matches = searchableText(bookmark).includes(lowered);
  }
  return token.excluded ? !matches : matches;
}

function groupTokens(tokens) {
  const groups = [[]];
  for (const token of tokens) {
    if (token.operator) groups.push([]);
    else groups.at(-1).push(token);
  }
  return groups.filter((group) => group.length);
}

export function matchesSearch(bookmark, query, matchMode = 'all', labelStates = new Map()) {
  for (const [label, state] of labelStates) {
    const hasLabel = bookmark.labels.some((item) => item.toLowerCase() === label.toLowerCase());
    if ((state === 'include' && !hasLabel) || (state === 'exclude' && hasLabel)) return false;
  }
  const { tokens } = tokenizeQuery(query.trim());
  if (!tokens.length) return true;
  const positivePlain = tokens.filter((token) => !token.operator && !token.excluded && !token.value.toLowerCase().startsWith('label:'));
  const conditions = tokens.filter((token) => !token.operator);
  if (matchMode === 'phrase' && positivePlain.length) {
    const phrase = positivePlain.map((token) => token.value).join(' ').toLowerCase();
    if (!searchableText(bookmark).includes(phrase)) return false;
    return conditions.filter((token) => token.excluded || token.value.toLowerCase().startsWith('label:')).every((token) => tokenMatches(bookmark, token));
  }
  if (matchMode === 'any' && positivePlain.length) {
    const anyPositive = positivePlain.some((token) => tokenMatches(bookmark, token));
    const required = conditions.filter((token) => token.excluded || token.value.toLowerCase().startsWith('label:'));
    return anyPositive && required.every((token) => tokenMatches(bookmark, token));
  }
  return groupTokens(tokens).some((group) => group.every((token) => tokenMatches(bookmark, token)));
}

/work/implementation/public/app.css.content:
:root { --ink:#24241f; --muted:#6d7067; --paper:#f7f5ef; --card:#fffdf8; --line:#dedbd1; --accent:#d65436; --accent-dark:#ad3e27; --green:#315f4e; --green-soft:#e3eee8; --danger:#a13d30; --warning:#f5e9d3; }
* { box-sizing:border-box; }
[hidden] { display:none !important; }
html { scroll-behavior:smooth; }
body { margin:0; min-height:100vh; color:var(--ink); background:var(--paper); font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
button,input,textarea { font:inherit; }
button { color:inherit; }
.app-shell { min-height:100vh; display:grid; grid-template-columns:230px minmax(0,1fr); }
.sidebar { position:sticky; top:0; height:100vh; display:flex; flex-direction:column; padding:30px 22px 24px; background:#edeae1; border-right:1px solid var(--line); }
.brand { display:flex; align-items:center; gap:11px; color:inherit; text-decoration:none; font-size:20px; font-weight:800; }
.brand-mark { width:35px; height:35px; display:grid; place-items:center; color:white; background:var(--accent); border-radius:10px 10px 10px 3px; font:700 20px Georgia,serif; }
.main-nav { display:grid; gap:5px; margin-top:54px; }
.nav-item { width:100%; display:flex; justify-content:space-between; align-items:center; padding:12px 13px; color:var(--muted); background:transparent; border:0; border-radius:8px; cursor:pointer; font-size:14px; font-weight:750; text-align:left; }
.nav-item:hover { background:rgba(255,255,255,.55); }
.nav-item.active { color:var(--accent); background:#fffaf3; box-shadow:inset 3px 0 var(--accent); }
.nav-item b { min-width:25px; padding:2px 6px; color:var(--muted); background:rgba(255,255,255,.65); border-radius:999px; font-size:11px; text-align:center; }
.sidebar-note { margin-top:auto; display:flex; gap:9px; align-items:flex-start; padding:13px; color:var(--muted); border:1px solid rgba(0,0,0,.07); border-radius:9px; font-size:12px; }
.sidebar-note p { margin:0; line-height:1.45; }.sidebar-note small { color:#8a8c84; }.pulse-dot { width:8px; height:8px; margin-top:4px; background:#4d8b6e; border-radius:50%; }
.main-content { min-width:0; padding:0 52px 90px; background:radial-gradient(circle at 90% 2%,rgba(214,84,54,.1),transparent 25rem),var(--paper); }
.mobile-header { display:none; }
.save-panel { max-width:1050px; padding:65px 0 48px; border-bottom:1px solid var(--line); }
.eyebrow { margin:0 0 10px; color:var(--accent); font-size:11px; font-weight:850; letter-spacing:.16em; }
h1 { max-width:840px; margin:0 0 32px; font:500 clamp(42px,5vw,66px)/1 Georgia,"Times New Roman",serif; letter-spacing:-.04em; }
#save-form { max-width:850px; } #save-form label { display:block; margin-bottom:9px; font-size:13px; font-weight:750; }
.save-row { display:grid; grid-template-columns:1fr auto; gap:9px; }.save-row input { min-width:0; padding:16px 17px; color:var(--ink); background:white; border:1px solid #c9c5b9; border-radius:8px; outline:none; box-shadow:0 3px 12px rgba(34,35,31,.04); }.save-row input:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(214,84,54,.13); }.save-row input[aria-invalid="true"] { border-color:var(--danger); box-shadow:0 0 0 3px rgba(161,61,48,.12); }
.save-row button { padding:0 21px; color:white; background:var(--accent); border:0; border-radius:8px; cursor:pointer; font-weight:800; }.save-row button:hover { background:var(--accent-dark); }.save-row button:disabled { opacity:.65; cursor:wait; }
.form-hint,.inline-error { margin:9px 0 0; font-size:12px; }.form-hint { color:var(--muted); }.inline-error { color:var(--danger); font-weight:750; }
.find-panel { max-width:1050px; padding:30px 0 24px; border-bottom:1px solid var(--line); }
.search-box { max-width:850px; display:grid; grid-template-columns:auto 1fr auto; gap:11px; align-items:center; padding:0 14px; background:white; border:1px solid #c9c5b9; border-radius:8px; box-shadow:0 3px 12px rgba(34,35,31,.04); }.search-box>span { color:var(--accent); font-size:25px; transform:rotate(-18deg); }.search-box input { min-width:0; padding:14px 0; color:var(--ink); background:transparent; border:0; outline:none; }.search-box kbd { padding:3px 7px; color:var(--muted); background:var(--paper); border:1px solid var(--line); border-radius:5px; font:11px ui-monospace,monospace; }
.match-controls,.query-help,.label-filter { display:flex; align-items:center; flex-wrap:wrap; gap:7px; max-width:850px; margin-top:11px; color:var(--muted); font-size:11px; }.match-controls>span,.label-filter>span { margin-right:3px; font-weight:750; }.match-controls button { padding:6px 9px; background:white; border:1px solid var(--line); border-radius:6px; cursor:pointer; font-weight:700; }.match-controls button.selected { color:white; background:var(--green); border-color:var(--green); }.query-help span { padding:5px 8px; background:rgba(255,255,255,.55); border:1px solid var(--line); border-radius:5px; }.query-help b { color:var(--ink); }.search-message { max-width:850px; margin-top:10px; padding:9px 11px; color:var(--green); background:var(--green-soft); border-radius:6px; font-size:12px; font-weight:700; }.search-message.warning { color:#6b4d29; background:var(--warning); }
.label-filter-list { display:flex; flex-wrap:wrap; gap:6px; }.filter-label { padding:6px 9px; color:var(--green); background:var(--green-soft); border:0; border-radius:999px; cursor:pointer; font-size:11px; font-weight:750; }.filter-label.include { color:white; background:var(--green); }.filter-label.exclude { color:white; background:var(--danger); text-decoration:line-through; }
.library { max-width:1050px; padding-top:33px; }.library-heading { display:flex; align-items:end; justify-content:space-between; margin-bottom:20px; }.library-heading h2 { margin:0; font:500 30px/1.1 Georgia,serif; }.result-count { color:var(--muted); font-size:13px; }.bookmark-list { display:grid; gap:13px; }
.bookmark-card { display:grid; grid-template-columns:auto minmax(0,1fr) auto; gap:17px; padding:22px; background:var(--card); border:1px solid var(--line); border-radius:11px; box-shadow:0 6px 24px rgba(34,35,31,.045); cursor:pointer; transition:.18s ease; }.bookmark-card:hover { border-color:#bcb8ad; box-shadow:0 10px 30px rgba(34,35,31,.08); transform:translateY(-1px); }.bookmark-card.highlight { border-color:var(--accent); box-shadow:0 0 0 4px rgba(214,84,54,.12); }.site-icon { width:45px; height:45px; display:grid; place-items:center; overflow:hidden; color:white; background:#345267; border-radius:10px; font:700 20px Georgia,serif; }.site-icon img { width:100%; height:100%; object-fit:cover; background:white; }.bookmark-meta { display:flex; flex-wrap:wrap; gap:7px; color:var(--muted); font-size:11px; }.site-name { color:var(--green); font-weight:800; }.bookmark-display h3 { margin:7px 0 5px; font:600 22px/1.22 Georgia,serif; }.description { margin:0 0 10px; color:#575a53; font-size:14px; line-height:1.5; }.bookmark-url { display:block; max-width:740px; overflow:hidden; color:var(--muted); font-size:11px; text-overflow:ellipsis; white-space:nowrap; }.card-tools { position:relative; display:flex; align-items:flex-start; gap:7px; }.icon-button,.more-button { width:34px; height:34px; display:grid; place-items:center; padding:0; color:var(--muted); background:white; border:1px solid var(--line); border-radius:50%; cursor:pointer; }.icon-button:hover,.more-button:hover { color:var(--accent); border-color:rgba(214,84,54,.4); }.more-button { padding-bottom:5px; border-radius:7px; font-weight:850; letter-spacing:1px; }
.card-menu { position:absolute; z-index:8; top:40px; right:0; min-width:180px; padding:5px; background:white; border:1px solid var(--line); border-radius:8px; box-shadow:0 14px 38px rgba(34,35,31,.16); }.card-menu button { width:100%; padding:9px 10px; background:white; border:0; border-radius:5px; cursor:pointer; font-size:12px; font-weight:750; text-align:left; }.card-menu button:hover { background:#f1eee6; }.card-menu .danger-action { margin-top:4px; padding-top:10px; color:var(--danger); border-top:1px solid var(--line); border-radius:0 0 5px 5px; }
.card-bottom { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-top:15px; }.labels { display:flex; flex-wrap:wrap; gap:6px; }.label-chip { display:inline-flex; align-items:center; gap:4px; padding:5px 8px; color:var(--green); background:var(--green-soft); border:0; border-radius:999px; font-size:11px; font-weight:750; }.label-chip.clickable { cursor:pointer; }.label-chip.clickable:hover { color:white; background:var(--green); }.remove-label { width:16px; height:16px; display:grid; place-items:center; padding:0; color:#5c756a; background:rgba(255,255,255,.65); border:0; border-radius:50%; cursor:pointer; line-height:1; }.remove-label:hover { color:white; background:var(--accent); }.later-button,.restore-button { flex:0 0 auto; display:flex; gap:5px; align-items:center; padding:7px 10px; color:var(--accent); background:white; border:1px solid rgba(214,84,54,.35); border-radius:7px; cursor:pointer; font-size:11px; font-weight:800; }.later-button.active { color:var(--green); background:var(--green-soft); border-color:transparent; }.restore-button { color:var(--green); border-color:rgba(49,95,78,.35); }
.quick-label { position:relative; display:inline-flex; align-items:center; gap:5px; }.add-label-button { padding:5px 8px; color:var(--muted); background:transparent; border:1px dashed #bcb8ad; border-radius:999px; cursor:pointer; font-size:11px; font-weight:750; }.label-entry { display:flex; gap:5px; }.label-entry input { width:145px; padding:6px 7px; border:1px solid #c9c5b9; border-radius:6px; outline:none; }.label-entry button { padding:6px 8px; color:white; background:var(--accent); border:0; border-radius:6px; cursor:pointer; font-size:11px; font-weight:750; }.label-entry button:disabled { opacity:.45; cursor:not-allowed; }.suggestions { position:absolute; z-index:10; top:34px; left:0; width:230px; padding:5px; background:white; border:1px solid var(--line); border-radius:8px; box-shadow:0 12px 34px rgba(34,35,31,.14); }.suggestions button { width:100%; display:flex; justify-content:space-between; padding:8px 9px; background:white; border:0; border-radius:5px; cursor:pointer; font-size:11px; text-align:left; }.suggestions button:hover { background:#f1eee6; }.suggestions small { color:var(--muted); }
.edit-form { display:grid; gap:9px; padding-top:11px; }.edit-form label { display:grid; gap:5px; color:var(--muted); font-size:11px; font-weight:750; }.edit-form input,.edit-form textarea { width:100%; padding:9px 10px; color:var(--ink); background:white; border:1px solid #c9c5b9; border-radius:6px; outline:none; resize:vertical; }.edit-form input:focus,.edit-form textarea:focus { border-color:var(--accent); box-shadow:0 0 0 3px rgba(214,84,54,.1); }.editor-labels { display:flex; flex-wrap:wrap; gap:5px; }.edit-actions { display:flex; justify-content:flex-end; gap:7px; }.edit-actions button,.failure-actions button { padding:8px 11px; color:white; background:var(--accent); border:0; border-radius:6px; cursor:pointer; font-size:11px; font-weight:800; }.edit-actions .secondary-button,.failure-actions .secondary-button { color:var(--ink); background:#ebe8df; }
.metadata-warning { display:flex; gap:9px; margin-top:14px; padding:11px; color:#6b4d29; background:var(--warning); border-radius:7px; font-size:12px; }.metadata-warning>span { width:21px; height:21px; display:grid; flex:0 0 auto; place-items:center; color:white; background:#a36b2d; border-radius:50%; font-weight:850; }.metadata-warning p { margin:2px 0 0; line-height:1.4; }.failure-actions { display:flex; gap:7px; margin-top:9px; }
.compact .bookmark-display h3 { display:-webkit-box; overflow:hidden; -webkit-box-orient:vertical; -webkit-line-clamp:2; }.compact .description { display:-webkit-box; overflow:hidden; -webkit-box-orient:vertical; -webkit-line-clamp:2; }.compact .label-chip.overflow-label { display:none; }.expand-button { margin-top:10px; padding:0; color:var(--accent); background:transparent; border:0; cursor:pointer; font-size:11px; font-weight:800; }
.empty-state { padding:52px 22px; text-align:center; background:rgba(255,255,255,.38); border:1px dashed #c9c5b9; border-radius:11px; }.empty-symbol { width:44px; height:44px; display:grid; place-items:center; margin:0 auto 14px; color:var(--accent); border:1px solid rgba(214,84,54,.3); border-radius:50%; font-size:21px; }.empty-state h3 { margin:0 0 6px; font:500 21px Georgia,serif; }.empty-state p { margin:0; color:var(--muted); line-height:1.5; }.empty-state button { margin-top:14px; padding:8px 11px; color:white; background:var(--accent); border:0; border-radius:6px; cursor:pointer; font-weight:750; }
.toast { position:fixed; z-index:30; right:22px; bottom:22px; max-width:min(420px,calc(100% - 44px)); padding:13px 16px; color:white; background:#273c33; border-radius:8px; box-shadow:0 12px 36px rgba(0,0,0,.22); font-size:13px; transform:translateY(90px); opacity:0; transition:.22s ease; }.toast.show { transform:translateY(0); opacity:1; }
.modal { width:min(500px,calc(100% - 32px)); padding:28px; color:var(--ink); background:var(--card); border:0; border-radius:13px; box-shadow:0 24px 90px rgba(0,0,0,.3); }.modal::backdrop { background:rgba(28,29,26,.6); }.modal h2 { margin:4px 0 10px; font:500 27px/1.2 Georgia,serif; }.modal p:not(.eyebrow) { color:var(--muted); line-height:1.5; }.warning-mark { width:38px; height:38px; display:grid; place-items:center; float:right; color:var(--danger); background:#f3dfdb; border-radius:50%; font-weight:850; }.danger { color:var(--danger); }.modal-actions { display:flex; justify-content:flex-end; gap:8px; margin-top:24px; }.modal-actions button { padding:9px 13px; border:0; border-radius:6px; cursor:pointer; font-weight:800; }.secondary-button { background:#ebe8df; }.danger-button { color:white; background:var(--danger); }
.loading { padding:60px; color:var(--muted); text-align:center; }
@media (max-width:850px) { .app-shell { grid-template-columns:1fr; }.sidebar { position:fixed; z-index:20; inset:62px auto 0 0; width:230px; height:auto; transform:translateX(-105%); transition:transform .2s ease; }.sidebar.open { transform:translateX(0); }.sidebar>.brand { display:none; }.mobile-header { height:62px; display:flex; align-items:center; justify-content:space-between; margin:0 -22px; padding:0 22px; background:rgba(247,245,239,.95); border-bottom:1px solid var(--line); }.mobile-header button { padding:7px 10px; background:white; border:1px solid var(--line); border-radius:6px; }.main-content { padding:0 22px 60px; }.save-panel { padding-top:48px; } }
@media (max-width:600px) { h1 { font-size:42px; }.save-row { grid-template-columns:1fr; }.save-row button { padding:14px; }.match-controls { align-items:flex-start; }.query-help { display:none; }.bookmark-card { grid-template-columns:auto minmax(0,1fr); padding:17px; }.card-tools { grid-column:2; grid-row:1; justify-content:flex-end; }.site-icon { grid-row:1; }.bookmark-copy { grid-column:1 / -1; }.card-bottom { align-items:flex-start; flex-direction:column; }.later-button,.restore-button { align-self:flex-end; } }

