for (const [name, viewport] of [['desktop', { width: 1440, height: 1000 }], ['mobile', { width: 390, height: 844 }]]) {
  const page = await browser.newPage({ viewport });
  await page.goto('http://127.0.0.1:4000/', { waitUntil: 'domcontentloaded' });
  await page.locator('[data-harness-ready="true"]').waitFor();
  await page.screenshot({ path: `/tmp/keep-${name}.png`, fullPage: true });
  console.log(name, await page.locator('#result-count').innerText(), await page.locator('[data-bookmark-id]').count());
  await page.close();
}
await browser.close();
